"""Build the complete same-pin Google walking audit and primary comparisons.
Input is 80 manually observed browser results, never inferred from the GIS model.
"""
import csv,json,math
from html import escape
from pathlib import Path
from urllib.parse import parse_qs,urlparse
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'data/processed/campus-walk';SOURCE=ROOT/'data/sources/google-maps/2026-11-01'
p=ROOT/'report-source/snapshot.json';s=json.loads(p.read_text(encoding='utf-8'))
supp={r['id']:r for r in s['queries']['campus_estimated_access']['rows']};sites={r['id']:r for r in s['queries']['campus_walk_sites']['rows']};original=s['queries']['campus_walking_routes']['rows'];complete={r['id']:r if r['available'] else supp[r['id']] for r in original}
observations=json.loads((SOURCE/'browser-observations.json').read_text(encoding='utf-8'))['rows'];assert len(observations)==80 and len({(r['building_id'],r['site']) for r in observations})==80
checks=[]
for obs in observations:
 row=complete[obs['building_id']];site=obs['site'];dest=sites['102' if site=='talley' else '131'];origin=row.get('entrance_coordinates') or row['access_coordinates'];end=dest['coordinates'];q=parse_qs(urlparse(obs['google_walking_url']).query)
 assert list(map(float,q['origin'][0].split(',')))==origin[::-1] and list(map(float,q['destination'][0].split(',')))==end[::-1]
 checks.append({**obs,'site_name':dest['name'],'group':row['group'],'gis_route_meters':row[site+'_m'],'gis_route_miles':row[site+'_m']/1609.344,'google_minus_gis_miles':obs['google_display_miles']-row[site+'_m']/1609.344,'origin_coordinates_lon_lat':origin,'destination_coordinates_lon_lat':end,'entrance_verified':False})
payload={'checked_on':'2026-11-01','collection_method':'All 80 primary suggested walking routes manually observed in the Google Maps browser UI with walking mode selected. No account data, API response or field measurement included.','coordinate_order':'longitude, latitude','scope':'All 40 housing buildings to both Talley and Western Boulevard, using the same public source access coordinates.','precision_and_limits':'Google displayed miles to one decimal and minutes as whole numbers. Google can choose different routes and resolve pins to a building, complex, cafe or nearby business. These are routing estimates, not verified door-to-door measurements. Google comparisons and averages are primary; GIS geometry and GIS averages remain a separate prototype.','rows':checks}
(SOURCE/'walking-checks.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
fields=['building_id','building_name','group','site','observed_on','gis_route_miles','google_display_miles','google_display_minutes','google_minus_gis_miles','google_suggested_via','google_resolved_origin','google_resolved_destination','google_walking_url','entrance_verified']
with (OUT/'google-walking-comparison.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(checks)
pairs=[]
for base in original:
 pair={'id':base['id'],'name':base['name'],'group':base['group']}
 for key in ['talley','western']:
  r=next(r for r in checks if r['building_id']==base['id'] and r['site']==key)
  pair[key+'_miles']=r['google_display_miles'];pair[key+'_minutes']=r['google_display_minutes'];pair[key+'_url']=r['google_walking_url']
 pair['difference_miles']=pair['western_miles']-pair['talley_miles'];pair['difference_minutes']=pair['western_minutes']-pair['talley_minutes'];pairs.append(pair)
averages=[]
for group in ['All housing','Residence halls','Wolf Village apartments','Wolf Ridge apartments']:
 rows=[r for r in pairs if group=='All housing' or r['group']==group];n=len(rows)
 avg={'group':group,'included_buildings':n,'total_buildings':n,'excluded_buildings':0,'source':'Google Maps walking directions, observed 2026-11-01'}
 for key in ['talley','western']:
  for unit in ['miles','minutes']:avg['sum_'+key+'_'+unit]=math.fsum(r[key+'_'+unit] for r in rows);avg['mean_'+key+'_'+unit]=avg['sum_'+key+'_'+unit]/n
 for unit in ['miles','minutes']:avg['mean_change_'+unit]=avg['mean_western_'+unit]-avg['mean_talley_'+unit]
 avg['farther_buildings']=sum(r['difference_miles']>1e-9 for r in rows);avg['closer_buildings']=sum(r['difference_miles']<-1e-9 for r in rows);avg['unchanged_buildings']=n-avg['farther_buildings']-avg['closer_buildings'];averages.append(avg)
(OUT/'google-averages.json').write_text(json.dumps({'weighting':'Equal weight per building; computed from displayed Google rounded miles and minutes, not hidden precision or GIS pace.','rows':averages},indent=2)+'\n',encoding='utf-8')
for filename,rows in [('google-distances.csv',pairs),('google-averages.csv',averages)]:
 with (OUT/filename).open('w',newline='',encoding='utf-8') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
source={'label':'Google Maps walking directions, all 80 public endpoint pairs','provider':'Google Maps browser UI','executedAt':'2026-11-01','period':'Suggested walks observed November 1, 2026; current network for both destinations','files':['data/sources/google-maps/2026-11-01/browser-observations.json','data/processed/campus-walk/google-distances.csv','data/processed/campus-walk/google-averages.csv'],'filters':['Walking mode selected; primary suggested route','40 housing buildings, both destinations, same public source coordinates','Equal building weights; Google rounded miles and whole minutes; no GIS pace conversion'],'metricDefinitions':[{'label':'Google mean walking change','formula':'sum(western miles)/same building count - sum(talley miles)/same building count; minutes use displayed Google walking minutes, not a fixed pace','definition':'A comparison of suggested Google walks. Rounded Google inputs and unresolved exact doorways limit precision. Google geometry is not the GIS prototype geometry.','componentIds':['voting-campus-walking-average']} ]}
s['queries']['campus_google_walks']={'rows':pairs,'source':source};s['queries']['campus_google_averages']={'rows':averages,'source':source};p.write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
tr=''.join(f'<tr><th>{escape(r["building_name"])}</th><td>{"Talley" if r["site"]=="talley" else "Western"}</td><td>{r["gis_route_miles"]:.2f} mi</td><td><a href="{escape(r["google_walking_url"],quote=True)}">{r["google_display_miles"]:.1f} mi · {r["google_display_minutes"]} min</a></td><td>{escape(r["google_suggested_via"])}</td></tr>' for r in checks)
avg=averages[0];halls=averages[1];ridge=averages[3]
block=f'''<!-- BEGIN GOOGLE WALKING CHECKS -->
<details id="google-walking-checks"><summary>Google walking directions: all 80 routes checked</summary><p>On November 1, 2026, we checked all 40 housing buildings to both sites in Google Maps, with walking mode selected and the same public access coordinates used in the GIS model. Google’s primary suggested walk supplies the default mileage, minutes and building averages. The GIS route drawings and GIS averages remain a separate prototype; they are not Google’s paths.</p><p>Google shows mileage rounded to one decimal and time in whole minutes. A Google average is an average of those displayed estimates, not a measurement with extra precision. The route selected by Google can change. Coordinates still do not verify actual residence and voting-room doors; Google resolves the Talley pin to Port City Java and the University Towers start to a nearby business. Original resolved labels and exact pins are preserved below.</p><ol><li>Add Google’s Talley mileage across the same 40 buildings: <strong>{avg['sum_talley_miles']:.1f} miles</strong>. Divide by 40: <strong>{avg['mean_talley_miles']:.3f} miles per building</strong>.</li><li>Add Google’s Western mileage: <strong>{avg['sum_western_miles']:.1f} miles</strong>. Divide by 40: <strong>{avg['mean_western_miles']:.3f} miles per building</strong>.</li><li>Subtract the means: <strong>{avg['mean_change_miles']:.3f} miles farther</strong>. Round to two decimals only for the displayed average.</li><li>Use Google’s minutes separately: ({avg['sum_western_minutes']:.0f} − {avg['sum_talley_minutes']:.0f}) ÷ 40 = <strong>{avg['mean_change_minutes']:.2f} minutes longer</strong>. We do not convert Google miles using the GIS model’s fixed pace.</li></ol><p><strong>Routing choice matters:</strong> for Wolf Ridge, Google shows Western {ridge['mean_change_miles']:.2f} mile farther on average, whereas the GIS model shows it closer. Google and GIS may choose different paths; this is not proof either doorway or route has been surveyed. The residence-hall Google average is {halls['mean_change_miles']:.2f} mile farther / {halls['mean_change_minutes']:.1f} minutes longer. Every building receives equal weight; these are not student-weighted averages.</p><table><thead><tr><th>Building</th><th>Destination</th><th>GIS path</th><th>Google walk</th><th>Google suggested via</th></tr></thead><tbody>{tr}</tbody></table><p><a href="data/processed/campus-walk/google-walking-comparison.csv">All 80 comparisons (.csv)</a> · <a href="data/processed/campus-walk/google-distances.csv">40 paired Google inputs (.csv)</a> · <a href="data/processed/campus-walk/google-averages.csv">Google sums and averages (.csv)</a> · <a href="data/sources/google-maps/2026-11-01/walking-checks.json">Observed values, resolved labels and exact pins</a> · <a href="https://developers.google.com/maps/documentation/urls/get-started">Google walking-link documentation</a>.</p></details>
<!-- END GOOGLE WALKING CHECKS -->'''
p=ROOT/'report-source/article-references.html';text=p.read_text(encoding='utf-8');start='<!-- BEGIN GOOGLE WALKING CHECKS -->';end='<!-- END GOOGLE WALKING CHECKS -->';a=text.index(start);b=text.index(end,a)+len(end);text=text[:a]+block+text[b:];p.write_text(text,encoding='utf-8')
print('Prepared 80 Google observations and 40 paired primary comparisons.')
for r in averages:print(r['group'],r['included_buildings'],round(r['mean_change_miles'],3),'mi',round(r['mean_change_minutes'],2),'min')
